import gradio as gr

# Wrapper function for Gradio interface format
def chat_interface(message, history):
    return respond_to_customer(message)

# Create the beautiful Chat UI
ui = gr.ChatInterface(
    fn=chat_interface,
    title="🤖 TechGadget Support Bot",
    description="Ask me about returns, warranties, or support hours! Powered by Gemini & RAG.",
    theme="soft"
)

# Launch it! (This will generate a public URL you can share with judges)
ui.launch(share=True)
